// The disable ban reads real comments only (LAB-7587, plan §5 R1-R3, R5-R7):
// text inside a string literal is not a comment, as each language's parser decides.
import { test } from "node:test";
import assert from "node:assert/strict";
import { mkdtempSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import path from "node:path";
import { extractAll } from "./extract.mjs";
import { check, file, goExtractor, makeRepo, run } from "./scenario-kit.mjs";

const BAN = /adds a size-lint disable comment; split the code instead\./;
const banAt = (p, n) => new RegExp(`::error file=${p.replace(".", "\\.")},line=${n}::${p.replace(".", "\\.")}:${n} adds a size-lint disable comment`);
const BASE = { "keep.go": file("go", 3) };

test("R1: a disable token inside a string literal is not banned", () => {
  for (const [p, line] of [
    ["a.go", 'var msg = "//nolint"'],
    ["a.py", 'text = "# noqa"'],
    ["a.ts", 'const s = "/* eslint-disable */";'],
    ["b.py", 'x = "# pylint: disable=R0915"'],
    ["b.go", 'func f() { fmt.Println("see //nolint:funlen docs") }'],
  ]) {
    const head = p.endsWith(".go") ? `package p\n\n${line}\n` : `${line}\n`;
    const r = check(makeRepo({ base: BASE, head: { [p]: head } }));
    assert.doesNotMatch(r.out, BAN, `${line}\n${r.out}`);
  }
});

test("R2: the same tokens in a real comment on an added line are still banned", () => {
  for (const [p, text, n] of [
    ["a.go", "package p\n\nvar y = 1 //nolint\n", 3],
    ["a.py", "x = 1  # noqa\n", 1],
    ["b.py", "def f():  # pylint: disable=R0915\n    pass\n", 1],
    ["a.ts", "/* eslint-disable */\nlet x = 1;\n", 1],
    ["b.ts", "let x = 1;\n/* eslint\n max-lines: off */\n", 2],
  ]) {
    const r = check(makeRepo({ base: BASE, head: { [p]: text } }));
    assert.equal(r.code, 1, r.out);
    assert.match(r.out, banAt(p, n), r.out);
  }
});

test("R3: a string holding /* does not hide the real multi-line directive after it", () => {
  const text = 'let a = 1;\nconst s = "/*";\n/* eslint\n max-lines: off */\nlet b = 2;\n';
  const r = check(makeRepo({ base: BASE, head: { "m.ts": text } }));
  assert.equal(r.code, 1, r.out);
  assert.match(r.out, banAt("m.ts", 3), r.out);
  assert.doesNotMatch(r.out, /line=[1245]::m\.ts/, r.out);
});

test("R5: extractAll passes comments through, and gives [] on a parse error", () => {
  const dir = mkdtempSync(path.join(tmpdir(), "size-gate-r5-"));
  try {
    const [ok, bad] = [path.join(dir, "ok.py"), path.join(dir, "bad.py")];
    writeFileSync(ok, 's = "# noqa"  # real\n');
    writeFileSync(bad, "def (:\n  # noqa\n");
    const out = extractAll([ok, bad], goExtractor());
    assert.deepEqual(out.get(ok).comments, [{ start: 1, end: 1, text: "# real" }]);
    assert.deepEqual(out.get(bad).comments, []);
    assert.ok(out.get(bad).error);
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
});

test("R6: renamed and untracked files are banned; generated and out-of-scope files are not", () => {
  const body = file("go", 20);
  const renamed = makeRepo({ base: { "old.go": body }, head: { "old.go": null, "new.go": body + "var y = 1 //nolint\n" } });
  assert.match(run(renamed.root, "diff", "--name-status", "-M", renamed.base, renamed.head), /^R\d+\told\.go\tnew\.go$/m);
  assert.match(check(renamed).out, banAt("new.go", 21));
  const untracked = makeRepo({ base: BASE, untracked: { "u.go": "package p\n\nvar y = 1 //nolint\n" } });
  assert.match(check(untracked).out, banAt("u.go", 3));
  const gen = "// Code generated by x. DO NOT EDIT.\n\npackage p\n\nvar y = 1 //nolint\n";
  const skipped = makeRepo({ base: BASE, head: { "g.go": gen, "vendor/v.go": "package v\n\nvar y = 1 //nolint\n", "a_test.go": "package p\n\nvar y = 1 //nolint\n" } });
  const r = check(skipped);
  assert.equal(r.code, 0, r.out);
  assert.doesNotMatch(r.out, BAN);
});

test("R7: an unparsable file with //nolint fails on cannot parse, with no ban error", () => {
  const r = check(makeRepo({ base: BASE, head: { "x.go": "package p\n\nfunc { //nolint\n" } }));
  assert.equal(r.code, 1, r.out);
  assert.match(r.out, /x\.go cannot parse: /);
  assert.doesNotMatch(r.out, BAN, r.out);
});
